import{_ as s,o as t,c as i,a0 as a}from"./chunks/framework.CR-yHhk1.js";const k=JSON.parse('{"title":"Convert a session between agents","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/convert-a-session.md","filePath":"how-to/convert-a-session.md"}'),o={name:"how-to/convert-a-session.md"};function n(d,e,r,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="convert-a-session-between-agents" tabindex="-1">Convert a session between agents <a class="header-anchor" href="#convert-a-session-between-agents" aria-label="Permalink to &quot;Convert a session between agents&quot;">​</a></h1><p>This guide shows how to move a session from one agent&#39;s store into another&#39;s — a Devin session resumed by <code>cline --id &lt;id&gt;</code>, a Cline session resumed by <code>devin -r &lt;id&gt;</code>, and so on.</p><p>Conversion is a store-to-store copy through the canonical IR: read the session out of the source store, write it into the target agent&#39;s layout, and hand back the id that agent resumes with. No intermediate file, no daemon — the store verbs work straight on the stores.</p><h2 id="the-three-routes" tabindex="-1">The three routes <a class="header-anchor" href="#the-three-routes" aria-label="Permalink to &quot;The three routes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want</th><th>Command</th></tr></thead><tbody><tr><td>a session in another agent&#39;s store</td><td><code>sepia install &lt;id&gt; --from &lt;a&gt; --to &lt;b&gt;</code></td></tr><tr><td>a portable copy on disk</td><td><code>sepia export &lt;id&gt; [out]</code> — IR JSON, or <code>--format cline</code> for a Cline session dir</td></tr><tr><td>a file from elsewhere in a store</td><td><code>sepia import &lt;path&gt; --to &lt;b&gt;</code></td></tr></tbody></table><p><code>install</code> is the convert verb: read → IR → write, printing the id to resume with. <code>export</code> + <code>import</code> is the same conversion split in two, for when you want to inspect or carry the copy yourself. An orchestrator gets the same operation as <code>sessions.convert</code> on the <a href="./../reference/serve-wire.html">serve wire</a>.</p><h2 id="convert-a-devin-session" tabindex="-1">Convert a Devin session <a class="header-anchor" href="#convert-a-devin-session" aria-label="Permalink to &quot;Convert a Devin session&quot;">​</a></h2><p><code>install</code> defaults to <code>--from devin --to cline</code>, so the bare form copies a Devin session into the Cline store:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> roomy-relative</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span></span></code></pre></div><p>Name the target explicitly to land somewhere else:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> roomy-relative</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> roomy-relative</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cursor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span></span></code></pre></div><p>The Cline target says where it went and how to pick it up:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Installed session roomy-relative into /home/you/.cline/data</span></span>
<span class="line"><span>Resume it with: cline --id roomy-relative -m &lt;model&gt;</span></span></code></pre></div><p>What each target writes, and how the agent resumes it:</p><table tabindex="0"><thead><tr><th>Target</th><th>Written</th><th>Resume with</th></tr></thead><tbody><tr><td><code>cline</code></td><td><code>&lt;data-dir&gt;/sessions/&lt;id&gt;/</code> (manifest + transcript) plus the index row</td><td><code>cline --id &lt;id&gt;</code></td></tr><tr><td><code>claude</code></td><td><code>&lt;claude-dir&gt;/projects/&lt;cwd-slug&gt;/&lt;id&gt;.jsonl</code></td><td>Claude Code&#39;s own resume over that project</td></tr><tr><td><code>cursor</code></td><td><code>&lt;cursor-dir&gt;/projects/&lt;cwd-slug&gt;/agent-transcripts/&lt;id&gt;/</code> plus <code>chats/&lt;hash&gt;/&lt;id&gt;/</code></td><td><code>cursor-agent --resume</code> from that project</td></tr><tr><td><code>devin</code></td><td><code>sessions</code>, <code>message_nodes</code>, <code>prompt_history</code> rows</td><td><code>devin -r &lt;id&gt;</code></td></tr></tbody></table><p>The Cline target also drops <code>&lt;id&gt;.sepia.json</code> next to the manifest: the IR sidecar sepia reads back from. Cline itself only loads the manifest and transcript, so the sidecar is invisible to it.</p><p>The source is only read: converting never edits the session you converted from (Devin&#39;s database is opened read-only).</p><h2 id="store-selection-and-the-default-dirs" tabindex="-1">Store selection and the default dirs <a class="header-anchor" href="#store-selection-and-the-default-dirs" aria-label="Permalink to &quot;Store selection and the default dirs&quot;">​</a></h2><p><code>--from</code>/<code>--to</code> name a store. <code>--db</code> sets where Devin&#39;s SQLite lives; the three <code>--*-dir</code> flags both point at a store <strong>and</strong> select it when the corresponding role is silent — which is why a single <code>--data-dir</code> is enough to write Cline layout into a scratch directory.</p><table tabindex="0"><thead><tr><th>Store</th><th>Path flag</th><th>Default</th></tr></thead><tbody><tr><td><code>devin</code></td><td><code>--db</code></td><td><code>~/.local/share/devin/cli/sessions.db</code></td></tr><tr><td><code>cline</code></td><td><code>--data-dir</code></td><td><code>~/.cline/data</code></td></tr><tr><td><code>claude</code></td><td><code>--claude-dir</code></td><td><code>~/.claude</code></td></tr><tr><td><code>cursor</code></td><td><code>--cursor-dir</code></td><td><code>~/.cursor</code></td></tr></tbody></table><p>When both forms appear, the explicit <code>--from</code>/<code>--to</code> wins; the path flag only decides the role that flag left unnamed.</p><p>Convert into a scratch directory first — it costs nothing and shows exactly what would land in a real agent store:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/probe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> roomy-relative</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> devin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/probe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/probe</span></span></code></pre></div><h2 id="ids-collisions-force" tabindex="-1">Ids, collisions, <code>--force</code> <a class="header-anchor" href="#ids-collisions-force" aria-label="Permalink to &quot;Ids, collisions, \`--force\`&quot;">​</a></h2><ul><li><code>--id &lt;new-id&gt;</code> installs under a different id. Without it <code>claude</code>, <code>cursor</code> and <code>devin</code> keep the session&#39;s own id — which is what makes a converted copy answer to the same <code>devin -r &lt;id&gt;</code> — while a Cline target derives a fresh id from the session&#39;s creation time and prints the one it chose.</li><li><code>claude</code> and <code>cursor</code> refuse an id that already exists in the target store — <code>pass --force to overwrite</code>.</li><li>A <code>devin</code> target leaves an existing session alone and says so (<code>already imported; leaving it untouched</code>); <code>--force</code> does not overwrite there.</li><li><code>--force</code> also lets a Cline install replace a session row a live session still owns.</li></ul><h2 id="what-survives-the-trip" tabindex="-1">What survives the trip <a class="header-anchor" href="#what-survives-the-trip" aria-label="Permalink to &quot;What survives the trip&quot;">​</a></h2><p>Everything the IR models: the node forest (branches, not a flat list), roles, text and non-text blocks, thinking <strong>with its provider signature</strong>, tool calls with arguments, status, locations and diffs, tool results with exit codes and timings, prompt history, checkpoints, and the meta overlay (title, working directory, model). Signatures are replayed verbatim so the target&#39;s model can keep using the transcript; fields a target store cannot express are marked <code>lossy</code> in metadata instead of dropped — see <a href="./../reference/session-formats.html">session formats</a>.</p><p>Transcripts are copied whole, so the cost scales with the source: a 40k-node Devin session lands as roughly 540 MB of Claude JSONL and converts in seconds. Budget disk, not patience.</p><h2 id="agent-configs-are-a-separate-install" tabindex="-1">Agent configs are a separate install <a class="header-anchor" href="#agent-configs-are-a-separate-install" aria-label="Permalink to &quot;Agent configs are a separate install&quot;">​</a></h2><p><code>sepia install</code> moves <em>sessions</em>. Rules, skills, commands, hooks, subagents and MCP servers convert with <code>sepia config install --from &lt;a&gt; --to &lt;b&gt;</code> — see <a href="./../reference/agent-configs.html">agent configs</a>.</p><h2 id="check-the-result" tabindex="-1">Check the result <a class="header-anchor" href="#check-the-result" aria-label="Permalink to &quot;Check the result&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # or --data-dir / --cursor-dir</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sepia</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> roomy-relative</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 400</span></span></code></pre></div><p>Listing it back with the right title and working directory means the target store&#39;s layout is right; <code>export</code> shows the IR that agent will hand back on the next read.</p>`,33)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
